async function refreshCurrencyRate(){if(Date.now()-new Date(fxReference.updatedAt).getTime()<86400000)return;try{const r=await fetch(FX_REFERENCE.endpoint,{signal:AbortSignal.timeout(5000)});if(!r.ok)return;const d=await r.json();if(d.result!=='success'||!Number.isFinite(d.rates?.INR)||d.rates.INR<=0)return;fxReference={rate:d.rates.INR,updatedAt:d.time_last_update_utc,source:FX_REFERENCE.source,endpoint:FX_REFERENCE.endpoint};fx=fxReference.rate;save('isv-fx-reference',fxReference);if(typeof revalueNativeCaps==='function')revalueNativeCaps();if(stocks.length)render()}catch{}}
function stockTickerLabel(s){return s.liveSymbol&&s.liveSource?s.liveSymbol+(s.liveSource==='NSE'?'.NS':'.BO'):s.referenceValuation&&s.referenceQuote?.symbol?s.referenceQuote.symbol+(s.referenceQuote.exchange==='NSE'?'.NS':'.BO'):s.currentTicker||s.ticker}
