function renderRows(){const interaction=captureRankingInteraction(),rankState=currentRankingState();rankSortMap=rankState.current.ranks;const list=chosen(),available=list.filter(s=>s.isin!==null&&s[metric]!=null).length,max=Math.max(1,Math.ceil(list.length/PAGE_SIZE));page=Math.min(page,max);$('#ranking-results').innerHTML=`<div class="count-line"><span>${list.length} companies <span class="divider">·</span> ${available} with ${metrics[metric].toLowerCase()} data</span><span>${currency} display</span></div>${!available&&list.length?`<div class="notice">${list.every(s=>s.isin===null)?'Current listing identities are unverified. Historical source values remain visible but are excluded from rankings.':metrics[metric]+' data is not available. Open a company for the original source. Missing values are never estimated.'}</div>`:''}<div class="table-wrap ranking-table" tabindex="0" role="region" aria-label="Company rankings, scroll for more rows"><table><thead><tr><th><span class="sr-only">Watchlist</span></th>${rankingHeader('rank','Rank / move','Sort by global rank for the selected metric')}${rankingHeader('name','Company')}${addedMetricHeaders()}${rankingHeader('metric','Market cap','Permanent market-cap column')}${rankingHeader('price','Stock price')}${rankingHeader('change','Day change')}${rankingHeader('trend','30-day trend','Sort by Zerodha price return over available observations in the last 30 calendar days; new listings use available history since listing')}${rankingHeader('sector','Sector')}<th>Compare</th></tr></thead><tbody>${list.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE).map(s=>`<tr><td><button class="star ${watch.has(s.ticker)?'saved':''}" data-watch="${s.rank}" aria-label="${watch.has(s.ticker)?'Remove':'Add'} ${escapeHtml(s.name)} ${watch.has(s.ticker)?'from':'to'} watchlist">${watch.has(s.ticker)?'★':'☆'}</button></td><td class="rank-cell">${rankMovementBadge(s,rankState)}</td><td class="left"><button class="company-cell" data-company="${s.rank}">${logo(s)}<span>${escapeHtml(s.name)}${isRecentIPO(s)?`<span class="new-ipo-badge" title="IPO listed ${s.verifiedListingDate} · ${escapeHtml(s.ipoSourceTitle||s.shareCountSourceTitle||'Exchange listing notice')}">[NEW]</span>`:''}<small>${escapeHtml(stockTickerLabel(s))} ${s.isin===null?'· Identity unverified':s.referenceValuation?'':s.eodQuote?'· '+s.eodQuote.exchange+' close':s.directoryOnly?'· Financial data pending':(feedMode==='live'||s.liveSymbol||s.referenceValuation)?'':/\.(NS|BO)$/.test(s.ticker)?'':'· ADR / overseas quote'}</small></span></button></td>${addedMetrics.map(k=>`<td class="number added-metric-cell" data-field="${k}">${metricValue(s,k)}</td>`).join('')}<td class="number" data-field="cap">${metricValue(s,'cap')}</td><td data-field="price">${stockPrice(s)}${feedMode==='live'?`<small class="live-time">${s.lastTrade?new Date(s.lastTrade).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'Waiting for quote'}${s.lastTrade?' IST':''}</small>`:''}</td><td data-field="change">${changeBadge(s)}</td><td data-field="trend">${spark(s)}</td><td class="left"><span class="sector-tag">${escapeHtml(s.sector)}</span></td><td><input type="checkbox" aria-label="Compare ${escapeHtml(s.name)}" data-compare="${s.rank}" ${compare.includes(s.ticker)?'checked':''}></td></tr>`).join('')}</tbody></table>${!list.length?`<div class="empty"><h3>${tab==='watchlist'&&!watch.size?'Start your watchlist':'No companies found'}</h3><p>${tab==='watchlist'&&!watch.size?'Tap the star beside any company to save it here.':'Try a different search or reset your filters.'}</p></div>`:''}</div><div class="pages"><span>Showing ${list.length?(page-1)*PAGE_SIZE+1:0}–${Math.min(page*PAGE_SIZE,list.length)} of ${list.length} companies</span><div><button data-page="${Math.max(1,page-1)}" ${page===1?'disabled':''}>← Previous</button><span class="page-numbers">${Array.from({length:max},(_,i)=>i+1).filter(n=>n===1||n===max||Math.abs(n-page)<=2).map((n,i,a)=>`${i&&n-a[i-1]>1?'<span> … </span>':''}<button data-page="${n}" aria-label="Page ${n}" ${n===page?'aria-current="page"':''} class="${n===page?'active':''}">${n}</button>`).join('')}</span><button data-page="${Math.min(max,page+1)}" ${page===max?'disabled':''}>Next →</button></div></div><p class="note">▲ / ▼ shows positions gained or lost versus the previous saved ranking in this browser. Movement is shown only when a previous saved rank exists and the position changed. Filters do not change the global rank.</p><p class="note">Coverage: ${stocks.length} ${feedMode==='live'?'exchange listings received from the feed (not deduplicated companies)':'securities from the snapshot and broker directory, deduplicated by ISIN where matched; this is not certified full-exchange coverage' }. Financial figures come from separate dated snapshots. <a class="source-link" href="#about">View sources & limitations ↗</a></p>`;document.querySelectorAll('[data-sort-column]').forEach(b=>b.onclick=()=>{const key=b.dataset.sortColumn;sortAsc=sortColumn===key?!sortAsc:['name','sector','rank','column:pe'].includes(key);sortColumn=key;page=1;renderRows();announceRanking('Sorted by '+(key.startsWith('column:')?metrics[key.slice(7)]:key==='metric'?'Market cap':key==='rank'?'Rank':key==='name'?'Company':key==='change'?'Day change':key==='trend'?'30-day trend':key==='price'?'Stock price':'Sector')+', '+(sortAsc?'ascending':'descending')+'.')});document.querySelectorAll('[data-remove-metric]').forEach(b=>b.onclick=()=>removeMetricColumn(b.dataset.removeMetric));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>changeRankingPage(+b.dataset.page));bindCompanies();restoreRankingInteraction(interaction)}
function changeRankingPage(nextPage){
 page=nextPage;renderRows();
 $('#ranking-results').scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
 document.querySelector('.ranking-table')?.focus({preventScroll:true});
 const count=chosen().length,start=count?(page-1)*PAGE_SIZE+1:0,end=Math.min(page*PAGE_SIZE,count);
 announceRanking('Page '+page+'. Showing '+start+'–'+end+' of '+count+' companies.');
}
function bindCompanies(){document.querySelectorAll('[data-company]').forEach(b=>b.onclick=e=>{e.preventDefault();openCompany(+b.dataset.company)});document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>{const s=stocks.find(x=>x.rank===+b.dataset.watch);watch.has(s.ticker)?watch.delete(s.ticker):watch.add(s.ticker);save('isv-watch',[...watch]);updateStats();if(tab==='watchlist')renderRows();else{b.classList.toggle('saved',watch.has(s.ticker));b.textContent=watch.has(s.ticker)?'★':'☆';b.setAttribute('aria-label',`${watch.has(s.ticker)?'Remove':'Add'} ${s.name} watchlist`)}});document.querySelectorAll('[data-compare]').forEach(b=>b.onchange=()=>{const s=stocks.find(x=>x.rank===+b.dataset.compare);if(b.checked&&compare.length>=4){b.checked=false;toast('Choose up to four companies to compare.');return}compare=b.checked?[...new Set([...compare,s.ticker])]:compare.filter(x=>x!==s.ticker);save('isv-compare',compare);toast(`${compare.length} selected · Open Compare to view`)})}
function sectorTotals(){return Object.entries(marketChartUniverse(stocks).reduce((a,s)=>(a[s.sector]=(a[s.sector]||0)+s.cap,a),{})).sort((a,b)=>b[1]-a[1])}
