function handleRouteChange(){
 if(['rankings','watchlist'].includes(tab)){const table=$('.ranking-table');rankingViewStates.set(tab,{page,signature:rankingViewSignature(),top:routeScrollHint&&routeScrollHint.to===location.hash&&(routeScrollHint.from||'#rankings')==='#'+tab?routeScrollHint.top:window.scrollY,tableTop:table?.scrollTop||0,tableLeft:table?.scrollLeft||0,focus:captureRankingInteraction().selector})}
 const next=location.hash.slice(1)||'rankings',saved=rankingViewStates.get(next),restore=saved?.signature===rankingViewSignature()?saved:null;
 const metricTabs=$('.stock-tabs'),sameCompany=tab==='stock'&&next.startsWith('stock/')&&metricTabs?.querySelector('a')?.getAttribute('href')?.split('/')[1]===next.split('/')[1],top=routeScrollHint?.to==='#'+next?routeScrollHint.top:window.scrollY,tabLeft=metricTabs?.scrollLeft||0,keepFocus=Boolean(metricTabs?.contains(document.activeElement));
 routeScrollHint=null;page=restore?.page||1;render();
 if(sameCompany){const tabs=$('.stock-tabs');if(tabs){tabs.scrollLeft=tabLeft;if(keepFocus){const selected=[...tabs.querySelectorAll('a')].find(a=>a.getAttribute('href')==='#'+next)||tabs.querySelector('select');selected?.focus({preventScroll:true})}}}
 window.scrollTo({top:sameCompany?top:restore?.top||0,behavior:'instant'});
 const table=$('.ranking-table');if(table&&restore){table.scrollTop=restore.tableTop;table.scrollLeft=restore.tableLeft}
 if(!sameCompany){const focusTarget=(restore?.focus?$(restore.focus):null)||$('#content h1')||$('#section-title')||$('#content');if(focusTarget){if(focusTarget.matches?.('h1,h2,h3'))focusTarget.setAttribute('tabindex','-1');focusTarget.focus({preventScroll:true})}}
}
document.body.classList.add('compact-rows');$('#theme').onclick=()=>{document.body.classList.toggle('dark');save('isv-dark',document.body.classList.contains('dark'));if(['charts','compare','stock'].includes(tab))render()};if(read('isv-dark',false))document.body.classList.add('dark');$('#currency').onchange=e=>{currency=e.target.value==='INR'?'INR':'USD';save('isv-currency',currency);render()};$('#detail .close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search'))location.hash='rankings';setTimeout(()=>$('#search')?.focus(),30)}if(e.key==='Enter'&&e.target.matches('circle[data-company]'))openCompany(+e.target.dataset.company)});document.querySelector('.skip-link').onclick=e=>{e.preventDefault();$('#content').focus();$('#content').scrollIntoView({block:'start'})};const routeEvent=()=>{if(renderedRoute!==location.hash)handleRouteChange()};window.onhashchange=routeEvent;window.addEventListener('popstate',routeEvent);$('#export').onclick=()=>{const ss=tab==='compare'?stocks.filter(s=>compare.includes(s.ticker)):['rankings','watchlist'].includes(tab)?chosen():stocks;const keys=[...new Set(['name','ticker','isin','liveSymbol','liveSource','quoteSource','quoteAsOf','quoteExchange','quoteSymbol','sector',...Object.keys(metrics),'price','sourcePriceINR','change','lastTrade','liveCapEstimated','liveCapINR','liveCapBasis','verifiedSharesOutstanding','shareCountDate','shareCountSource','shareCountSourceTitle','identitySource','identityEffectiveDate'])];const csv=[[`Exported ${new Date().toISOString()}; prices ${feedMode==='kite'||feedMode==='live'?'INR':'USD'}; cap/revenue/earnings/assets/netAssets/liabilities/debt/cash USD billions; EPS source units; traded value INR; sourcePriceINR/liveCapINR INR; verifiedSharesOutstanding count; daily change percent; financial periods differ; see lastTrade and shareCountDate per company`],keys,...ss.map(s=>keys.map(k=>s[k]??''))].map(row=>row.map(csvCell).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='india-stock-view-'+tab+'-'+new Date(Date.now()+330*60000).toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(`Exported ${ss.length} rows · source units are listed in the CSV header`)};
let sourceLoadInFlight=null,sourceLoadWarnings=[],sourceSupportingPending=false;
function showDataAvailability(){
 const notice=$('#data-availability');if(!notice)return;notice.hidden=!sourceLoadWarnings.length&&!sourceSupportingPending;notice.classList.toggle('supporting-pending',sourceSupportingPending&&!sourceLoadWarnings.length);
 notice.innerHTML=(sourceSupportingPending?'<span>Loading supporting company data…</span> ':'')+(sourceLoadWarnings.length?'<span>Some data is unavailable: '+sourceLoadWarnings.map(escapeHtml).join(', ')+'. Available companies remain usable.</span> <button id="retry-sources">Retry data</button>':'');
 const retry=$('#retry-sources');if(retry)retry.onclick=loadWebsiteData;
}
function applyWebsiteSources({data:[d,master,shareData,ipoData,reviewedData,supplementalData],warnings},supportingPending=false){
  $('#content').removeAttribute('aria-busy');sourceLoadWarnings=warnings;sourceSupportingPending=supportingPending;
  supplementalIPORecords=supplementalData.records;officialIPORecords=[...supplementalIPORecords,...ipoData.records];reviewedShareRecords=reviewedData.records;officialShareRecords=[...shareData.records,...reviewedShareRecords];db=d;
  snapshotStocks=d.stocks.map((s,i)=>({...s,rank:i+1,sector:getSector(s.name)}));instruments=master.listings;
  stocks=attachIPOListings(attachOfficialShares(mergeRankingUniverse(snapshotStocks,instruments),officialShareRecords),officialIPORecords);
  watch=new Set(canonicalSavedTickers(stocks,[...watch]));compare=canonicalSavedTickers(stocks,compare);
  feedMode='snapshot';showDataAvailability();render();
}
function loadWebsiteData(){
 if(sourceLoadInFlight)return sourceLoadInFlight;
 $('#content').setAttribute('aria-busy','true');$('#content').innerHTML='<div class="site-loading" role="status">Loading market data…</div>';
 sourceLoadInFlight=loadMarketSources(fetch,!db?data=>applyWebsiteSources(data,true):null).then(data=>{applyWebsiteSources(data);initLive();
 }).catch(()=>{sourceSupportingPending=false;showDataAvailability();$('#content').removeAttribute('aria-busy');$('#content').innerHTML='<div class="empty" role="alert"><h3>Company data couldn’t load</h3><p>Your saved watchlist is safe. Check your connection and try again.</p><button id="retry-data">Try again</button></div>';$('#retry-data').onclick=loadWebsiteData}).finally(()=>{sourceLoadInFlight=null});
 return sourceLoadInFlight;
}
if(document.readyState!=='complete')document.addEventListener('DOMContentLoaded',loadWebsiteData,{once:true});else loadWebsiteData();

Object.assign(metrics,{price:'Price',volume:'Volume',change:'Day change'});
function renderLiveStats(){const nse=stocks.filter(s=>s.exchange==='NSE'&&s.price!=null).length,bse=stocks.filter(s=>s.exchange==='BSE'&&s.price!=null).length;$('#stats').innerHTML=[['NSE LISTINGS RECEIVED',nse,'Separate exchange listings'],['BSE LISTINGS RECEIVED',bse,'Separate exchange listings'],['ADVANCERS',stocks.filter(s=>s.change>0).length,'Received quotes only'],['DECLINERS',stocks.filter(s=>s.change<0).length,'Received quotes only']].map(([label,value,note])=>`<div class="stat"><div class="stat-label">${label}</div><strong>${value.toLocaleString('en-IN')}</strong></div>`).join('');$('#watch-count').textContent=watch.size}
let feedReadInFlight=null;const marketUpdateStore=createMarketDeltaStore();
async function readFeed(){if(feedReadInFlight)return feedReadInFlight;feedReadInFlight=(async()=>{if(STATIC_PREVIEW)return {status:{state:'not_configured',provider:'Official exchange reports',configured:false},quotes:[]};try{const r=await fetch('/api/market?quotes=1&changes=1'+(marketUpdateStore.cursor()?'&since='+encodeURIComponent(marketUpdateStore.cursor()):''),{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error();const payload=await r.json();if(!payload.status||!Array.isArray(payload.quotes))throw Error();if(Array.isArray(payload.listings))liveDirectory=payload.listings;return marketUpdateStore.merge(payload)}catch{return {status:{...feedStatus,state:'disconnected',provider:feedStatus?.provider||(feedMode==='kite'?'Zerodha Kite':'Market data'),configured:feedStatus?.configured||false,authenticated:feedStatus?.authenticated||false,connections:0,refreshFailed:true},quotes:[]}}})();try{return await feedReadInFlight}finally{feedReadInFlight=null}}
function updateFeedLabel(){const st=feedStatus?.state;$('#feed-state').classList.toggle('feed-connected',feedMode==='live'&&st==='streaming');if(feedMode==='snapshot')$('#feed-state').textContent=officialSnapshotLabel();else $('#feed-state').textContent=(st==='streaming'?'Feed connected':st==='disconnected'?'Disconnected · last received quotes':'Feed waiting')+' · '+(feedStatus?.received||0)+' quotes / '+stocks.length+' listings';$('#currency').disabled=false}
function showFeedPanel(){renderExchangeSources()}

function applyLiveQuotes(quotes){const lookup=new Map(snapshotStocks.filter(s=>/\.(NS|BO)$/.test(s.ticker)).map(s=>[(s.ticker.endsWith('.BO')?'BSE:':'NSE:')+s.ticker.replace(/\.(NS|BO)$/,''),s]));const byId=new Map(quotes.map(q=>[q.id,q]));const entries=liveDirectory.length?liveDirectory.map(d=>({...d,id:d.exchange+':'+d.symbol,...(byId.get(d.exchange+':'+d.symbol)||{})})):quotes;stocks=entries.map((q,i)=>{const meta=lookup.get(q.id);return {...q,ticker:q.id,rank:i+1,sector:meta?.sector||'Unclassified',name:meta?.name||q.name||q.symbol,logo:meta?.logo||null,cap:null}});updateFeedLabel()}
let feedPollingStarted=false;
async function initLive(){const payload=await readFeed();feedStatus=payload.status;updateFeedLabel();if(payload.status.provider==='Zerodha Kite'&&payload.status.authenticated&&payload.quotes.length){applyKiteQuotes(payload);if(['stock','index','compare','charts'].includes(tab)){updateStats();refreshKiteView()}else render()}updateFeedLabel();$('#feed-button').onclick=async()=>{const payload=await readFeed();feedStatus=payload.status;showFeedPanel();$('#feed-dialog').showModal()};$('#feed-dialog .close').onclick=()=>$('#feed-dialog').close();if(STATIC_PREVIEW||feedPollingStarted)return;feedPollingStarted=true;setInterval(async()=>{if(document.hidden)return;const payload=await readFeed();feedStatus=payload.status;updateFeedLabel();if(payload.status.refreshFailed)return;if(payload.status.provider==='Zerodha Kite'&&payload.status.authenticated&&payload.quotes.length){const signature=marketQuoteSignature(payload);if(window.kiteSignature!==signature){window.kiteSignature=signature;applyKiteQuotes(payload);refreshKiteView()}return}if(feedMode==='live'){applyLiveQuotes(payload.quotes);if(!$('#detail').open&&!$('#feed-dialog').open){const focused=document.activeElement?.id;if(focused!=='search')render();else{updateStats();renderRows()}}}},5000)}
function renderLiveCharts(){const gainers=stocks.filter(s=>s.change!=null).sort((a,b)=>b.change-a.change).slice(0,10),losers=stocks.filter(s=>s.change!=null).sort((a,b)=>a.change-b.change).slice(0,10);$('#content').innerHTML=`<div class="notice">Rankings cover received exchange listings, not unique companies or confirmed full-market coverage. Prices are INR. Stale quotes retain their trade timestamps.</div><div class="chart-grid">${[['Top gainers',gainers],['Top decliners',losers]].map(([title,ss])=>`<article class="card"><h3>${title}</h3>${ss.length?ss.map(s=>`<div class="bar-row"><button class="company-cell" data-company="${s.rank}">${escapeHtml(s.symbol)}</button><div class="bar-track"><div class="bar-fill" style="background:${s.change<0?'var(--down)':'var(--up)'};width:${Math.min(100,Math.abs(s.change)/Math.max(1,...ss.map(x=>Math.abs(x.change)))*100)}%"></div></div>${changeBadge(s)}</div>`).join(''):'<p class="note">Waiting for exchange quotes.</p>'}</article>`).join('')}</div>`;bindCompanies()}
let instruments=[],liveDirectory=[],directoryQuery='',directoryExchange='All exchanges',directoryPage=1;
async function renderDirectory(){if(!instruments.length){try{const response=await fetch('instruments.json');const master=await response.json();instruments=master.listings}catch{$('#content').innerHTML='<div class="empty">Company directory could not be loaded.</div>';return}}
const ss=instruments.filter(s=>(directoryExchange==='All exchanges'||s.exchange===directoryExchange)&&`${s.name} ${s.symbol} ${s.isin}`.toLowerCase().includes(directoryQuery.toLowerCase()));const pages=Math.max(1,Math.ceil(ss.length/PAGE_SIZE));directoryPage=Math.min(pages,directoryPage);const logos=new Map(snapshotStocks.filter(s=>/\.(NS|BO)$/.test(s.ticker)).map(s=>[s.ticker.replace(/\.(NS|BO)$/,''),s.logo]));
$('#content').innerHTML=`<div class="notice">${instruments.length.toLocaleString('en-IN')} company equity listings in the downloaded Upstox BOD directory · ${new Set(instruments.map(s=>s.isin)).size.toLocaleString('en-IN')} distinct ISINs · Quotes require the live feed. Excludes ETFs, bonds and suspended instruments. Directory download: 30 Oct 2026.</div><div class="controls"><label class="search">⌕ <input id="directory-search" aria-label="Search all listings" placeholder="Search company, symbol or ISIN…" value="${escapeHtml(directoryQuery)}"></label><select id="directory-exchange" aria-label="Directory exchange">${['All exchanges','NSE','BSE'].map(v=>option(v,v,directoryExchange)).join('')}</select><span class="coverage-chip">${ss.length.toLocaleString('en-IN')} listings</span></div><div class="table-wrap"><table><thead><tr><th class="left">Company</th><th>Symbol</th><th>Exchange</th><th>ISIN</th><th>Live quotes</th></tr></thead><tbody>${ss.slice((directoryPage-1)*PAGE_SIZE,directoryPage*PAGE_SIZE).map(s=>`<tr><td class="left"><span class="company-cell">${logo({...s,logo:logos.get(s.symbol)})}<span>${escapeHtml(s.name)}<small>${escapeHtml(s.group)} · company equity</small></span></span></td><td>${escapeHtml(s.symbol)}</td><td>${s.exchange}</td><td>${escapeHtml(s.isin)}</td><td class="note">Feed required</td></tr>`).join('')}</tbody></table>${!ss.length?'<div class="empty">No matching listings.</div>':''}</div><div class="pages"><span>Page ${directoryPage} of ${pages}</span><div><button id="directory-prev" ${directoryPage===1?'disabled':''}>← Previous</button><button id="directory-next" ${directoryPage===pages?'disabled':''}>Next →</button></div></div><p class="note">A company may have multiple exchange listings. Missing company logos use a neutral icon. <a class="source-link" href="https://upstox.com/developer/api-documentation/instruments/" target="_blank" rel="noopener">Directory source ↗</a></p>`;
$('#directory-search').oninput=e=>{const pos=e.target.selectionStart;directoryQuery=e.target.value;directoryPage=1;renderDirectory().then(()=>{$('#directory-search').focus();$('#directory-search').setSelectionRange(pos,pos)})};$('#directory-exchange').onchange=e=>{directoryExchange=e.target.value;directoryPage=1;renderDirectory()};$('#directory-prev').onclick=()=>{directoryPage--;renderDirectory()};$('#directory-next').onclick=()=>{directoryPage++;renderDirectory()};}

// Keep the rankings universe in sync with the server's refreshed directory.
setInterval(async()=>{if(STATIC_PREVIEW||document.hidden||feedMode!=='snapshot')return;try{const response=await fetch('instruments.json',{cache:'no-store'});if(!response.ok)return;const master=await response.json();const signature=master.listings.map(s=>s.exchange+':'+s.symbol+':'+s.isin).join('|');if(signature===instruments.map(s=>s.exchange+':'+s.symbol+':'+s.isin).join('|'))return;instruments=master.listings;stocks=attachIPOListings(attachOfficialShares(mergeRankingUniverse(snapshotStocks,instruments),officialShareRecords),officialIPORecords);if(!$('#detail').open)render()}catch{}},60000);

